-- Production schema starter. Configure Supabase Auth and RLS before deployment.
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role text default 'user', status text default 'active', created_at timestamptz default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, title text not null, tool text, status text default 'draft', created_at timestamptz default now());
create table if not exists transactions(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, amount numeric default 0, coins integer default 0, status text default 'pending', created_at timestamptz default now());
create table if not exists support_tickets(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, subject text, message text, status text default 'open', created_at timestamptz default now());
